import react from 'react';
function Hero(){
return(
   <>
   <section className="container-fluid" id="supportHero">
    
    <div className="p-5 mt-5 mb-5" id="supportWrapper">
      <h4>Support Portal</h4>  
      <a href="">Track Tickets</a>
    </div>
    <div className="row p-5 mt-5 mb-5">
        <div className="col-6 p-5 mt-5 mb-5">
            <h2>search for an answer or browse help topics to create a ticket</h2>
       <input placeholder='Eg: how do i activate F&O, why is my order getting rejected.'></input>
        </div>
       <div className="col-6 p-5 mt-5 mb-5">
        <h2>Featured</h2>
       </div>
      
    </div>
   </section>
   </>
);

}
export default Hero;
